Clase Producto
    Privado Definir precio Como Entero;

    Metodo Constructor(unPrecio Como Entero)
        Este.precio <- unPrecio;
    FinMetodo

    Publico Metodo PrecioConDescuento(porcentaje Como Entero) Como Real
        Retornar Este.precio - Este.precio * porcentaje / 100;
    FinMetodo
FinClase

Proceso CalcularDescuento
    Definir precio Como Entero;
    Definir porcentaje Como Entero;
    Definir producto Como Producto;
    Leer precio;
    Leer porcentaje;
    producto <- Nuevo Producto(precio);
    Escribir producto.PrecioConDescuento(porcentaje);
FinProceso
